import click
from click.testing import CliRunner
r = CliRunner()

# group with default_map for subcommand
@click.group()
def cli(): pass

@cli.command()
@click.option("--flag", is_flag=True)
def sub(flag): click.echo(f"flag={flag}")

res = r.invoke(cli, ["sub"], default_map={"sub": {"flag": True}})
print("group sub map:", repr(res.output), res.exception)

# count
@click.command()
@click.option("-v", count=True)
def c(v): click.echo(f"v={v}")
res = r.invoke(c, [], default_map={"v": 3})
print("count map:", repr(res.output), res.exception)

# multiple flag
@click.command()
@click.option("--flag", is_flag=True, multiple=True)
def m(flag): click.echo(f"{flag}")
res = r.invoke(m, [], default_map={"flag": True})
print("multiple flag map:", repr(res.output), res.exception)

# non-bool flag with default on the *other* flag
@click.command()
@click.option('--upper', 'transformation', flag_value='upper')
@click.option('--lower', 'transformation', flag_value='lower', default=True)
def info(transformation): click.echo(repr(transformation))
res = r.invoke(info, [], default_map={"transformation": "upper"})
print("nonbool map upper:", repr(res.output), res.exception)
res = r.invoke(info, [])
print("nonbool no map:", repr(res.output), res.exception)
